 11	import { Injectable, Logger } from '@nestjs/common';
 12	import { IAIProvider, IAIExecutionInput, IProviderHealthStatus } from './interfaces';
 13	import { ClaudeCodeProvider } from './providers';
 14	import { ExecutionService } from '../execution/execution.service';
 15	import { AICostTrackerService } from '../cost-tracking/ai-cost-tracker.service';
 16	import { AIProvider } from '@/prisma/enums';
 17	
 18	@Injectable()
 19	export class AIExecutionService {
 20	  private readonly logger = new Logger(AIExecutionService.name);
 21	
 22	  /** Provider registry */
 23	  private readonly providers: Map<AIProvider, IAIProvider> = new Map();
 24	
 25	  constructor(
 26	    private readonly claudeProvider: ClaudeCodeProvider,
 27	    private readonly executionService: ExecutionService,
 28	    private readonly costTracker: AICostTrackerService,
 29	  ) {
 30	    // Register Claude Code via adapter
 31	    this.providers.set(AIProvider.CLAUDE_CODE, {
 32	      provider: AIProvider.CLAUDE_CODE,
 33	      maxConcurrent: 5,
 34	      defaultTimeoutMs: 3600 * 1000,
 35	      execute: async (input: IAIExecutionInput) => {
 36	        // Build basic payload from input for legacy compatibility
 37	        return this.claudeProvider.execute({
 38	          ticketId: input.ticketId,
 39	          executionId: input.executionId,
 40	          aiProvider: AIProvider.CLAUDE_CODE,
 41	          priority: 1,
 42	          prompt: input.prompt,
 43	          repositoryUrl: input.repositoryUrl,
 44	          projectId: '',
 45	          // targetBranch intentionally omitted — provider auto-generates dsf/<ticket>/<exec> branch
 46	          targetFiles: input.targetFiles,
 47	          complexityScore: 5, // Default complexity
 48	        });
 49	      },
 50	      checkHealth: async () => {
 51	        const isHealthy = await this.claudeProvider.isHealthy();
 52	        return {
 53	          provider: AIProvider.CLAUDE_CODE,
 54	          isHealthy,
 55	          lastSuccessAt: isHealthy ? new Date() : null,
 56	          lastFailureAt: isHealthy ? null : new Date(),
 57	          consecutiveFailures: isHealthy ? 0 : 1,
 58	          circuitState: isHealthy ? 'CLOSED' : 'OPEN',
 59	          activeExecutions: 0,
 60	        };
 61	      },
 62	      cancel: async () => {
 63	        this.logger.log(`Cancel requested for Claude execution, not supported in legacy adapter`);
 64	      },
 65	    } as IAIProvider);
 66	  }
 67	
 68	  /**
 69	   * Get provider instance for specialized orchestration (Story 14.1 Fix)
 70	   */
 71	  getProvider(provider: AIProvider): IAIProvider | undefined {
 72	    return this.providers.get(provider);
 73	  }
 74	
 75	  /**
 76	   * Get provider health status
 77	   */
 78	  async getProviderHealth(provider: AIProvider): Promise<IProviderHealthStatus | null> {
 79	    const aiProvider = this.providers.get(provider);
 80	    if (!aiProvider) {
 81	      return null;
 82	    }
 83	    return aiProvider.checkHealth();
 84	  }
 85	
 86	  /**
 87	   * Get all providers health
 88	   */
 89	  async getAllProvidersHealth(): Promise<IProviderHealthStatus[]> {
 90	    const health: IProviderHealthStatus[] = [];
 91	
 92	    for (const provider of this.providers.values()) {
 93	      health.push(await provider.checkHealth());
 94	    }
 95	
 96	    return health;
 97	  }
 98	
 99	  /**
100	   * Cancel an ongoing execution
101	   */
102	  async cancelExecution(
103	    provider: AIProvider,
104	    executionId: string,
105	    correlationId: string,
106	  ): Promise<void> {
107	    const aiProvider = this.providers.get(provider);
108	    if (aiProvider) {
109	      await aiProvider.cancel(executionId);
110	    }
111	
112	    await this.executionService.cancelExecution(executionId, 'Cancelled by user', correlationId);
113	  }
114	
115	  /**
116	   * Check if provider is available
117	   */
118	  async isProviderAvailable(provider: AIProvider): Promise<boolean> {
119	    const health = await this.getProviderHealth(provider);
120	    return health?.isHealthy ?? false;
121	  }
122	}

